class CameraPublisher(Node):
    def __init__(self):
        super().__init__('camera_publisher')

        #--- base picture
        self.init_base_picture()

        self.publisher_ = self.create_publisher(Twist, '/TB3RoboAvatar_cmd_pos', 10)

        #--- callback
        timer_period = 0.01  # 秒
        self.timer = self.create_timer(timer_period, self.camera_callback)

    #--- camera callback
    def camera_callback(self, ):
        picture = self.take_capture()
        self.search_angle_position(picture)

    #--- take capture
    def take_capture(self, ):
        camera_cap = cv2.VideoCapture(0)
        ret, frame = camera_cap.read()
        # cv2.imwrite('./test.png', frame)
        camera_cap.release()
        return frame
    
